INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_05','V242','Nguyễn Minh',5,'我想今天下午请假休息，晚上也早点睡觉，咱们作息稍微调整一下可以吗？','wǒ xiǎng jīn tiān xià wǔ qǐng jià xiū xī， wǎn shàng yě zǎo diǎn shuì jiào， zán men zuò xī shāo wēi tiáo zhěng yī xià kě yǐ ma？','Em muốn chiều nay xin nghỉ để nghỉ ngơi, tối cũng ngủ sớm hơn, mình điều chỉnh giờ giấc một chút được không anh?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_06','V242','Lâm Vũ',6,'当然没问题啊！你好好休息就行，我晚上小声一点，不打扰你。','dāng rán méi wèn tí a！ nǐ hǎo hǎo xiū xī jiù xíng， wǒ wǎn shàng xiǎo shēng yì diǎn， bù dǎ rǎo nǐ。','Đương nhiên không vấn đề gì! Em cứ nghỉ ngơi cho khỏe, tối anh nói khẽ lại, không làm phiền em đâu.','AM05') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_07','V242','Nguyễn Minh',7,'太谢谢你了，真的麻烦你啦！','tài xiè xiè nǐ le， zhēn de má fán nǐ la！','Cảm ơn anh nhiều lắm, thật sự làm phiền anh rồi!','AM02') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_08','V242','Lâm Vũ',8,'客气啥，室友本来就该互相照顾的嘛。','kè qì shá， shì yǒu běn lái jiù gāi hù xiāng zhào gù de ma。','Khách sáo gì chứ, ở chung phòng vốn dĩ phải quan tâm nhau mà.','AM09') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT243','S7','Hỏi quy định đăng ký khách đến thăm ký túc','Có bạn muốn đến thăm buổi tối nhưng ký túc cấm khách ban đêm','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V243','SIT243','P1','twist','ban_chinh_thuc','Có bạn muốn đến thăm buổi tối nhưng ký túc cấm khách ban đêm',NULL) ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_01','V243','Nguyễn Minh',1,'王阿姨您好，打扰您了！我想咨询一下访客入校的规定。','wáng ā yí nín hǎo， dǎ rǎo nín le！ wǒ xiǎng zī xún yī xià fǎng kè rù xiào de guī dìng。','Cô Vương ơi, làm phiền cô rồi ạ! Em muốn hỏi thăm về quy định khách vào trường ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_02','V243','Quản lý',2,'你好，是有朋友要来宿舍找你吗？','nǐ hǎo， shì yǒu péng yǒu yào lái sù shè zhǎo nǐ ma？','Chào em, có bạn muốn đến ký túc tìm em à?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_03','V243','Nguyễn Minh',3,'对的，我同学明天想来宿舍找我，需要怎么登记呀？','duì de， wǒ tóng xué míng tiān xiǎng lái sù shè zhǎo wǒ， xū yào zěn me dēng jì ya？','Dạ đúng ạ, bạn học của em mai muốn đến ký túc tìm em, cần đăng ký như thế nào ạ?','AM01') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_04','V243','Quản lý',4,'很简单的，白天来访带身份证，在门卫处登记信息就可以啦。','hěn jiǎn dān de， bái tiān lái fǎng dài shēn fèn zhèng， zài mén wèi chù dēng jì xìn xī jiù kě yǐ la。','Đơn giản thôi, ban ngày đến thăm thì mang theo chứng minh thư, đăng ký thông tin ở chỗ bảo vệ là được rồi.','AM02') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_05','V243','Nguyễn Minh',5,'那晚上可以来访吗？我本来约了晚上见面的。','nà wǎn shàng kě yǐ lái fǎng ma？ wǒ běn lái yuē le wǎn shàng jiàn miàn de。','Vậy buổi tối có đến được không ạ? Em vốn đã hẹn gặp vào buổi tối.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_06','V243','Quản lý',6,'晚上不行哦，宿舍十点锁门，晚间禁止外来人员入校的。','wǎn shàng bù xíng ó， sù shè shí diǎn suǒ mén， wǎn jiān jìn zhǐ wài lái rén yuán rù xiào de。','Tối thì không được đâu, ký túc khóa cửa lúc mười giờ, buổi tối cấm người ngoài vào trường.','AM03') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_07','V243','Nguyễn Minh',7,'原来是这样，那我改到白天吧，谢谢您告知我！','yuán lái shì zhè yàng， nà wǒ gǎi dào bái tiān ba， xiè xiè nín gào zhī wǒ！','Thì ra là vậy, vậy em đổi sang ban ngày ạ, cảm ơn cô đã cho em biết!','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_08','V243','Quản lý',8,'没事的，提前安排好就行，记得让你朋友带证件哈。','méi shì de， tí qián ān pái hǎo jiù xíng， jì de ràng nǐ péng yǒu dài zhèng jiàn hā。','Không sao đâu, sắp xếp trước là được rồi, nhớ nhắc bạn em mang theo giấy tờ nhé.','AM06') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT244','S7','Báo chủ nhà đổi giờ nhận phòng vì chuyến bay trễ','Chuyến bay bị hoãn, xin lỗi và thương lượng lại giờ nhận phòng','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V244','SIT244','P1','that_bai_nhe','ban_chinh_thuc','Chuyến bay bị hoãn, xin lỗi và thương lượng lại giờ nhận phòng','提前主动告知行程变动，中国人一般不会严厉追责，但短期房屋预留存在时间限制，过夜空置房东有权收取空置费用；诚恳沟通大多可以免除额外收费。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_01','V244','阮明',1,'刘哥您好，不好意思打扰您休息，有件事需要跟您协商调整。','liú gē nín hǎo， bù hǎo yì sī dǎ rǎo nín xiū xī， yǒu jiàn shì xū yào gēn nín xié shāng diào zhěng。','Chào anh Lưu, xin lỗi vì đã làm phiền anh nghỉ ngơi, có việc em cần trao đổi và điều chỉnh với anh.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_02','V244','房东',2,'你好同学，我记得咱们约定好今天下午两点过来办理房屋入住的对吧？','nǐ hǎo tóng xué， wǒ jì de zán men yuē dìng hǎo jīn tiān xià wǔ liǎng diǎn guò lái bàn lǐ fáng wū rù zhù de duì ba？','Chào em, anh nhớ là mình hẹn hai giờ chiều nay đến làm thủ tục nhận phòng đúng không?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_03','V244','阮明',3,'非常抱歉！我乘坐的入境航班大面积延误，落地时间推迟六个小时，今天肯定赶不过来了呢。','fēi cháng bào qiàn！ wǒ chéng zuò de rù jìng háng bān dà miàn jī yán wù， luò dì shí jiān tuī chí liù gè xiǎo shí， jīn tiān kěn dìng gǎn bù guò lái le ne。','Em xin lỗi anh rất nhiều! Chuyến bay nhập cảnh của em bị hoãn trên diện rộng, giờ hạ cánh trễ mất sáu tiếng, hôm nay chắc chắn không kịp đến được ạ.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_04','V244','房东',4,'这样啊？我今天专门空出一下午在家等你交接，临时变动确实有点麻烦。','zhè yàng a？ wǒ jīn tiān zhuān mén kòng chū yī xià wǔ zài jiā děng nǐ jiāo jiē， lín shí biàn dòng què shí yǒu diǎn má fán。','Vậy à? Hôm nay anh đã đặc biệt để trống cả buổi chiều ở nhà chờ giao nhận nhà cho em, thay đổi đột xuất thế này quả thật hơi phiền.','AM05') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_05','V244','阮明',5,'我特别理解您的不便，机场工作人员说最快明天下午两点才能抵达市区。','wǒ tè bié lǐ jiě nín de bù biàn， jī chǎng gōng zuò rén yuán shuō zuì kuài míng tiān xià wǔ liǎng diǎn cái néng dǐ dá shì qū。','Em rất hiểu sự bất tiện của anh, nhân viên sân bay nói sớm nhất cũng phải hai giờ chiều mai mới đến được trung tâm thành phố.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_06','V244','房东',6,'我原本计划今天交接完房屋，晚上出门办事，现在行程全部打乱了。','wǒ yuán běn jì huà jīn tiān jiāo jiē wán fáng wū， wǎn shàng chū mén bàn shì， xiàn zài háng chéng quán bù dǎ luàn le。','Anh vốn định hôm nay giao nhận nhà xong thì tối đi có việc, giờ lịch trình bị xáo trộn hết cả rồi.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_07','V244','阮明',7,'能不能麻烦您帮我延后一天入住，明天下午我准时到，绝不再次迟到？','néng bù néng má fán nín bāng wǒ yán hòu yī tiān rù zhù， míng tiān xià wǔ wǒ zhǔn shí dào， jué bù zài cì chí dào？','Anh có thể giúp em dời lại một ngày nhận phòng được không ạ, chiều mai em sẽ đến đúng giờ, tuyệt đối không trễ nữa?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_08','V244','房东',8,'按理当天预留的房间只能保留至当日深夜，过夜预留需要额外收取半天空置费。','àn lǐ dàng tiān yù liú de fáng jiān zhǐ néng bǎo liú zhì dāng rì shēn yè， guò yè yù liú xū yào é wài shōu qǔ bàn tiān kōng zhì fèi。','Theo quy định phòng giữ trong ngày chỉ được giữ đến nửa đêm hôm đó thôi, giữ qua đêm thì phải tính thêm phí bỏ trống nửa ngày.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_09','V244','阮明',9,'我明白规则，只要能保留房间，相关费用我可以正常承担。','wǒ míng bái guī zé， zhǐ yào néng bǎo liú fáng jiān， xiāng guān fèi yòng wǒ kě yǐ zhèng cháng chéng dān。','Em hiểu quy định mà, chỉ cần giữ được phòng, chi phí liên quan em sẽ thanh toán bình thường.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_10','V244','房东',10,'看你是留学生刚来国内不容易，空置费我就不收了，但今天房间不再单独为你预留。','kàn nǐ shì liú xué shēng gāng lái guó nèi bù róng yì， kōng zhì fèi wǒ jiù bù shōu le， dàn jīn tiān fáng jiān bù zài dān dú wèi nǐ yù liú。','Thấy em là du học sinh mới sang cũng không dễ dàng gì, phí bỏ trống anh sẽ không thu, nhưng hôm nay phòng sẽ không giữ riêng cho em nữa.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_11','V244','阮明',11,'太感谢您的理解和体谅，临时行程变动给您添了不少麻烦，真的不好意思！','tài gǎn xiè nín de lǐ jiě hé tǐ liàng， lín shí xíng chéng biàn dòng gěi nín tiān le bù shǎo má fán， zhēn de bù hǎo yì sī！','Cảm ơn anh rất nhiều vì đã thông cảm và thấu hiểu, việc thay đổi lịch trình đột xuất này gây phiền cho anh không ít, thật sự xin lỗi anh!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_12','V244','房东',12,'不用客气，出门在外难免有突发变动嘛，但是明天抵达前一小时一定要提前跟我说一声。','bù yòng kè qì， chū mén zài wài nán miǎn yǒu tū fā biàn dòng ma， dàn shì míng tiān dǐ dá qián yī xiǎo shí yí dìng yào tí qián gēn wǒ shuō yī shēng。','Không cần khách sáo đâu, đi xa khó tránh khỏi chuyện phát sinh bất ngờ mà, nhưng trước khi đến vào ngày mai một tiếng thì nhất định phải báo trước cho anh một tiếng nhé.','AM09') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_13','V244','阮明',13,'我一定提前发消息告知您到站时间，方便您提前到家等候。','wǒ yí dìng tí qián fā xiāo xī gào zhī nín dào zhàn shí jiān， fāng biàn nín tí qián dào jiā děng hòu。','Em nhất định sẽ nhắn tin báo trước giờ em đến ga cho anh, để anh tiện về nhà chờ trước.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_14','V244','房东',14,'好，那我们就约定明天下午两点办理入住，明天见！','hǎo， nà wǒ men jiù yuē dìng míng tiān xià wǔ liǎng diǎn bàn lǐ rù zhù， míng tiān jiàn！','Được, vậy mình hẹn hai giờ chiều mai làm thủ tục nhận phòng, hẹn gặp em ngày mai!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT301','S101','Hỏi giá và khuyến mãi ở siêu thị',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V301','SIT301','P1','suon_se','tuy_y',NULL,'国内商超日常促销多为即时抵扣、买赠模式，无需凑单，活动规则简单直白。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_01','V301','阮明',1,'你好，请问这款纯牛奶多少钱一箱啊？','nǐ hǎo， qǐng wèn zhè kuǎn chún niú nǎi duō shǎo qián yī xiāng a？','Chào chị, cho em hỏi loại sữa tươi nguyên chất này giá bao nhiêu một thùng ạ?','AM05') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_02','V301','导购员',2,'这款68一箱，我们这两天刚好有活动呢。','zhè kuǎn 68 yī xiāng， wǒ men zhè liǎng tiān gāng hǎo yǒu huó dòng ne。','Loại này 68 tệ một thùng, mấy hôm nay đang có chương trình khuyến mãi đó.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_03','V301','阮明',3,'那是什么优惠呀，划算吗？','nà shì shén me yōu huì ya， huá suàn ma？','Vậy ưu đãi gì vậy chị, có lời không ạ?','AM01') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_04','V301','导购员',4,'买一箱送一小盒酸奶，买两箱直接减20块，很划算的。','mǎi yī xiāng sòng yī xiǎo hé suān nǎi， mǎi liǎng xiāng zhí jiē jiǎn 20 kuài， hěn huá suàn de。','Mua một thùng tặng một hộp sữa chua nhỏ, mua hai thùng thì giảm thẳng 20 tệ, lời lắm đó.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_05','V301','阮明',5,'这样啊，那我买两箱吧，平时喝得多。','zhè yàng a， nà wǒ mǎi liǎng xiāng ba， píng shí hē dé duō。','Vậy à, thế thì em mua hai thùng luôn, nhà em cũng hay uống.','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_06','V301','导购员',6,'可以的，我帮你扫一下，结账自动抵扣。','kě yǐ de， wǒ bāng nǐ sǎo yī xià， jié zhàng zì dòng dǐ kòu。','Được rồi, để chị quét mã cho em, lúc tính tiền sẽ tự động trừ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_07','V301','阮明',7,'好嘞，谢谢你！','hǎo lei， xiè xiè nǐ！','Dạ vâng, cảm ơn chị!','AM08') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT302','S101','Cân rau quả và tự thanh toán',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V302','SIT302','P1','twist','tuy_y',NULL,'国内超市生鲜蔬果必须自助称重贴价签，无标签商品无法通过自助结账，是通用规则。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_01','V302','阮明',1,'阿姨，请问蔬菜水果是在这里称重的吧？','ā yí， qǐng wèn shū cài shuǐ guǒ shì zài zhè lǐ chēng zhòng de ba？','Cô ơi, rau củ quả là cân ở đây đúng không ạ?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_02','V302','阿姨',2,'对的呀，把东西放上去选对应的菜名就行。','duì de ya， bǎ dōng xī fàng shàng qù xuǎn duì yìng de cài míng jiù xíng。','Đúng rồi đó, con để đồ lên rồi chọn đúng tên rau là được.','AM01') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_03','V302','阮明',3,'奇怪，我按了好几次，怎么都不出标签呢？','qí guài， wǒ àn le hǎo jǐ cì， zěn me dōu bù chū biāo qiān ne？','Lạ ghê, con bấm mấy lần rồi mà sao không ra tem vậy cô?','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_04','V302','阿姨',4,'我看看，你选的是大白菜，你拿的是青菜，选错品类啦。','wǒ kàn kàn， nǐ xuǎn de shì dà bái cài， nǐ ná de shì qīng cài， xuǎn cuò pǐn lèi la。','Để cô xem, con chọn cải thảo mà con lại cầm rau cải xanh, chọn sai loại rồi đó.','AM02') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_05','V302','阮明',5,'原来是这样，难怪一直不行，我重新弄一下。','yuán lái shì zhè yàng， nán guài yì zhí bù xíng， wǒ chóng xīn nòng yī xià。','Thì ra là vậy, thảo nào cứ không được, để con làm lại.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_06','V302','阿姨',6,'没事，慢慢来，打好标签就可以去自助机结账了。','méi shì， màn màn lái， dǎ hǎo biāo qiān jiù kě yǐ qù zì zhù jī jié zhàng le。','Không sao, cứ từ từ, in tem xong là ra máy tự thanh toán được rồi.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_07','V302','阮明',7,'太感谢您了，不然我得卡好久。','tài gǎn xiè nín le， bù rán wǒ dé kǎ hǎo jiǔ。','Cảm ơn cô nhiều lắm, không thì con phải loay hoay lâu lắm.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT303','S101','Đổi trả hàng bị lỗi',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V303','SIT303','P1','suon_se','ban_chinh_thuc',NULL,'国内正规商超在售后期内，非人为损坏的商品，可凭购物凭证无条件退换货；生鲜食品变质优先全额退款，避免顾客再次购买同类问题产品。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_01','V303','阮明',1,'你好，我有一件商品存在质量问题，想来售后窗口处理退换。','nǐ hǎo， wǒ yǒu yī jiàn shāng pǐn cún zài zhì liàng wèn tí， xiǎng lái shòu hòu chuāng kǒu chǔ lǐ tuì huàn。','Chào chị, em có một món hàng bị lỗi chất lượng, muốn đến quầy hậu mãi để xử lý đổi trả.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_02','V303','店员',2,'您好，麻烦先跟我说一下是什么商品，什么时候在店内购买的？','nín hǎo， má fán xiān gēn wǒ shuō yī xià shì shén me shāng pǐn， shén me shí hòu zài diàn nèi gòu mǎi de？','Chào em, phiền em nói qua giúp chị là hàng gì, mua ở cửa hàng lúc nào vậy?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_03','V303','阮明',3,'是一款全麦吐司面包，昨天傍晚在生鲜烘焙区选购的，今天早上拆开就发霉了。','shì yī kuǎn quán mài tǔ sī miàn bāo， zuó tiān bàng wǎn zài shēng xiān hōng bèi qū xuǎn gòu de， jīn tiān zǎo shàng chāi kāi jiù fā méi le。','Là bánh mì nguyên cám ạ, em mua chiều tối hôm qua ở khu bánh tươi, sáng nay mở ra thì đã bị mốc rồi.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_04','V303','店员',4,'麻烦出示一下对应的购物小票，我们需要核对购买时间和批次信息。','má fán chū shì yī xià duì yìng de gòu wù xiǎo piào， wǒ men xū yào hé duì gòu mǎi shí jiān hé pī cì xìn xī。','Phiền em cho chị xem hóa đơn mua hàng tương ứng, chị cần đối chiếu thời gian mua và thông tin lô hàng.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_05','V303','阮明',5,'小票我一直妥善收在钱包里，现在拿给您，我全程常温存放，根本没放多久呀。','xiǎo piào wǒ yì zhí tuǒ shàn shōu zài qián bāo lǐ， xiàn zài ná gěi nín， wǒ quán chéng cháng wēn cún fàng， gēn běn méi fàng duō jiǔ ya。','Hóa đơn em vẫn cất cẩn thận trong ví, giờ em đưa chị đây, em bảo quản ở nhiệt độ thường suốt, cũng đâu để lâu gì đâu ạ.','AM01') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_06','V303','店员',6,'我对照系统入库记录核对面包批次，确认是商品本身出厂保鲜出现问题，非常抱歉哈。','wǒ duì zhào xì tǒng rù kù jì lù hé duì miàn bāo pī cì， què rèn shì shāng pǐn běn shēn chū chǎng bǎo xiān chū xiàn wèn tí， fēi cháng bào qiàn hā。','Chị đối chiếu ghi chép nhập kho trong hệ thống với lô bánh này, xác nhận là do khâu bảo quản xuất xưởng của sản phẩm có vấn đề, chị xin lỗi em nhiều nhé.','AM06') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_07','V303','阮明',7,'没关系，我也不是故意为难店里，只是担心同类商品其他顾客买到。','méi guān xì， wǒ yě bú shì gù yì wéi nán diàn lǐ， zhǐ shì dān xīn tóng lèi shāng pǐn qí tā gù kè mǎi dào。','Không sao đâu chị, em cũng không cố ý làm khó cửa hàng, chỉ lo là khách khác cũng mua phải loại hàng này thôi.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_08','V303','店员',8,'您愿意换新商品，还是直接申请全额退款，两种方案都可以执行。','nín yuàn yì huàn xīn shāng pǐn， hái shì zhí jiē shēn qǐng quán é tuì kuǎn， liǎng zhǒng fāng àn dōu kě yǐ zhí xíng。','Em muốn đổi hàng mới hay là làm thủ tục hoàn tiền toàn bộ luôn, cả hai cách đều được cả.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_09','V303','阮明',9,'这款面包我不敢再选购同款，直接办理全额退款会更合适。','zhè kuǎn miàn bāo wǒ bù gǎn zài xuǎn gòu tóng kuǎn， zhí jiē bàn lǐ quán é tuì kuǎn huì gèng hé shì。','Loại bánh này em không dám mua lại nữa, hoàn tiền toàn bộ sẽ hợp lý hơn ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_10','V303','店员',10,'没问题，我现在操作后台退款，资金会原路返还到您付款的支付软件。','méi wèn tí， wǒ xiàn zài cāo zuò hòu tái tuì kuǎn， zī jīn huì yuán lù fǎn huán dào nín fù kuǎn de zhī fù ruǎn jiàn。','Không vấn đề gì, giờ chị thao tác hoàn tiền trên hệ thống, tiền sẽ hoàn về đúng ứng dụng thanh toán em đã dùng.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_11','V303','阮明',11,'退款到账大概需要多长时间，会不会有延迟？','tuì kuǎn dào zhàng dà gài xū yào duō zhǎng shí jiān， huì bú huì yǒu yán chí？','Tiền hoàn về khoảng bao lâu vậy chị, có bị chậm trễ gì không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_12','V303','店员',12,'线上支付退款实时到账，您现在打开手机就能查到余额变动。','xiàn shàng zhī fù tuì kuǎn shí shí dào zhàng， nín xiàn zài dǎ kāi shǒu jī jiù néng chá dào yú é biàn dòng。','Hoàn tiền thanh toán online là về ngay lập tức, em mở điện thoại lên là thấy số dư thay đổi liền.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_13','V303','阮明',13,'清楚流程了，给您添麻烦实在不好意思。','qīng chǔ liú chéng le， gěi nín tiān má fán shí zài bù hǎo yì sī。','Em hiểu quy trình rồi ạ, làm phiền chị nhiều thật sự xin lỗi.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_14','V303','店员',14,'是我们商品存在质量瑕疵，本该向您致歉，您慢走。','shì wǒ men shāng pǐn cún zài zhì liàng xiá cī， běn gāi xiàng nín zhì qiàn， nín màn zǒu。','Là do sản phẩm bên chị bị lỗi chất lượng, đáng lẽ phải xin lỗi em mới đúng, em đi cẩn thận nhé.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_15','V303','阮明',15,'好的，麻烦你啦。','hǎo de， má fán nǐ la。','Dạ vâng, phiền chị nhiều rồi ạ.','AM02') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT304','S102','Mua chăn, gối, nồi, ly cho phòng mới',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V304','SIT304','P1','twist','tuy_y',NULL,'国内高校宿舍严禁大功率电器，校园店铺售卖的煮锅均为合规小功率产品，不会违规跳闸。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_01','V304','阮明',1,'老板，我是新生，想买一套宿舍被褥、枕头还有小煮锅。','lǎo bǎn， wǒ shì xīn shēng， xiǎng mǎi yī tào sù shè bèi rù、 zhěn tou hái yǒu xiǎo zhǔ guō。','Anh ơi, em là sinh viên mới, muốn mua một bộ chăn ga gối ký túc với cả nồi nấu nhỏ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_02','V304','老板',2,'有的，这些都是学生专用的，厚度和功率都适配宿舍的。','yǒu de， zhè xiē dōu shì xué shēng zhuān yòng de， hòu dù hé gōng lǜ dōu shì pèi sù shè de。','Có chứ, mấy món này đều là loại chuyên dùng cho sinh viên, độ dày và công suất đều phù hợp với ký túc hết.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_03','V304','阮明',3,'这个被子冬天盖够厚吗？我怕冷的。','zhè ge bèi zi dōng tiān gài gòu hòu ma？ wǒ pà lěng de。','Cái chăn này mùa đông đắp có đủ ấm không anh? Em sợ lạnh lắm.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_04','V304','老板',4,'足够过冬的，就是宿舍小煮锅今天刚卖断货了嘛。','zú gòu guò dōng de， jiù shì sù shè xiǎo zhǔ guō jīn tiān gāng mài duàn huò le ma。','Đủ để qua mùa đông luôn, chỉ có điều nồi nấu nhỏ cho ký túc hôm nay vừa bán hết hàng rồi.','AM09') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_05','V304','阮明',5,'啊？那什么时候能补货呀？我急用。','a？ nà shén me shí hòu néng bǔ huò ya？ wǒ jí yòng。','Hả? Vậy khi nào có hàng lại vậy anh? Em đang cần gấp.','AM01') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_06','V304','老板',6,'明天中午就到货，你明天过来拿就行。','míng tiān zhōng wǔ jiù dào huò， nǐ míng tiān guò lái ná jiù xíng。','Trưa mai là có hàng về rồi, mai em qua lấy là được.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_07','V304','阮明',7,'行，那我今天先买被子、枕头和水杯。','xíng， nà wǒ jīn tiān xiān mǎi bèi zi、 zhěn tou hé shuǐ bēi。','Vâng, vậy hôm nay em mua trước chăn, gối với ly nước.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT305','S103','Mua nước giặt và dùng máy giặt tự động',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V305','SIT305','P1','suon_se','tuy_y',NULL,'国内高校宿舍洗衣房均为无人自助设备，按次计费，无需人工值守，操作简单。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_01','V305','阮明',1,'学姐，请问哪种洗衣液好用啊？我第一次在宿舍洗衣服。','xué jiě， qǐng wèn nǎ zhǒng xǐ yī yè hǎo yòng a？ wǒ dì yī cì zài sù shè xǐ yī fú。','Chị ơi, cho em hỏi loại nước giặt nào dùng tốt vậy chị? Em lần đầu giặt đồ ở ký túc.','AM05') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_02','V305','学姐',2,'你买这款瓶装的就行，味道清淡，去污力也不错呢。','nǐ mǎi zhè kuǎn píng zhuāng de jiù xíng， wèi dào qīng dàn， qù wū lì yě bù cuò ne。','Em mua loại chai này là được, mùi nhẹ nhàng, tẩy sạch cũng tốt lắm đó.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_03','V305','阮明',3,'好嘞，那楼下自助洗衣机难操作吗？','hǎo lei， nà lóu xià zì zhù xǐ yī jī nán cāo zuò ma？','Dạ được, vậy máy giặt tự động ở dưới lầu có khó dùng không chị?','AM08') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_04','V305','学姐',4,'一点不难，扫码付款、放衣服和洗衣液就可以啦。','yì diǎn bù nán， sǎo mǎ fù kuǎn、 fàng yī fú hé xǐ yī yè jiù kě yǐ la。','Không khó chút nào, quét mã thanh toán, bỏ quần áo với nước giặt vào là xong.','AM02') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_05','V305','阮明',5,'需要自己调时间和模式吗？','xū yào zì jǐ diào shí jiān hé mó shì ma？','Có cần tự chỉnh thời gian với chế độ giặt không chị?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_06','V305','学姐',6,'不用，默认标准模式，洗得很干净的。','bù yòng， mò rèn biāo zhǔn mó shì， xǐ dé hěn gān jìng de。','Không cần đâu, mặc định chế độ tiêu chuẩn, giặt sạch lắm.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_07','V305','阮明',7,'明白了，太谢谢你啦！','míng bái le， tài xiè xiè nǐ la！','Em hiểu rồi ạ, cảm ơn chị nhiều nha!','AM02') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT306','S103','Máy giặt hết tiền giữa chừng, xin hoàn tiền',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V306','SIT306','P1','suon_se','ban_chinh_thuc',NULL,'校园自助设备出现扣费异常、中途停机等问题，均可找宿管统一走后勤退款流程；退款不会即时处理，学校后勤固定日期批量结算。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_01','V306','阮明',1,'阿姨您好，我刚刚在宿舍楼自助洗衣房洗衣服，机器运行一半突然停机了。','ā yí nín hǎo， wǒ gāng gāng zài sù shè lóu zì zhù xǐ yī fáng xǐ yī fú， jī qì yùn xíng yí bàn tū rán tíng jī le。','Cô ơi, cháu vừa giặt đồ ở tiệm giặt tự động trong ký túc xá, máy đang chạy nửa chừng thì tự nhiên dừng lại ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_02','V306','宿管阿姨',2,'别着急，你先回忆一下，机器停机的时候屏幕有没有弹出提示文字？','bié zháo jí， nǐ xiān huí yì yī xià， jī qì tíng jī de shí hòu píng mù yǒu méi yǒu dàn chū tí shì wén zì？','Đừng lo, cháu thử nhớ lại xem lúc máy dừng thì màn hình có hiện thông báo gì không?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_03','V306','阮明',3,'屏幕显示账户余额不足，自动中断洗涤程序，衣服只洗了一半。','píng mù xiǎn shì zhàng hù yú é bù zú， zì dòng zhōng duàn xǐ dí chéng xù， yī fú zhǐ xǐ le yí bàn。','Màn hình báo số dư tài khoản không đủ, chương trình giặt tự động bị ngắt, quần áo mới giặt được nửa chừng ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_04','V306','宿管阿姨',4,'原来是扣费余额耗尽，这种情况在自助设备使用里十分常见。','yuán lái shì kòu fèi yú é hào jìn， zhè zhǒng qíng kuàng zài zì zhù shè bèi shǐ yòng lǐ shí fēn cháng jiàn。','Thì ra là hết tiền trong tài khoản, tình trạng này khá thường gặp khi dùng máy tự động lắm.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_05','V306','阮明',5,'我之前查看余额还有几块钱，以为完全够完整洗完一整轮，没想到中途欠费了。','wǒ zhī qián chá kàn yú é hái yǒu jǐ kuài qián， yǐ wéi wán quán gòu wán zhěng xǐ wán yī zhěng lún， méi xiǎng dào zhōng tú qiàn fèi le。','Lúc trước cháu kiểm tra thấy vẫn còn vài đồng, tưởng là đủ để giặt xong hết một lượt, ai ngờ giữa chừng lại thiếu tiền.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_06','V306','宿管阿姨',6,'洗衣程序分为洗涤、漂洗、脱水三段，分段扣取费用，余额不够就会中途停机。','xǐ yī chéng xù fēn wéi xǐ dí、 piǎo xǐ、 tuō shuǐ sān duàn， fēn duàn kòu qǔ fèi yòng， yú é bù gòu jiù huì zhōng tú tíng jī。','Chương trình giặt chia làm ba bước: giặt, xả, vắt, mỗi bước trừ tiền riêng, không đủ số dư là nó dừng giữa chừng luôn.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_07','V306','阮明',7,'那像我这种只洗一半就停机的情况，可以申请退还部分洗衣费用吗？','nà xiàng wǒ zhè zhǒng zhǐ xǐ yí bàn jiù tíng jī de qíng kuàng， kě yǐ shēn qǐng tuì huán bù fèn xǐ yī fèi yòng ma？','Vậy trường hợp như cháu, mới giặt được nửa chừng thì máy dừng, có xin hoàn lại một phần tiền giặt được không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_08','V306','宿管阿姨',8,'完全可以，后勤处专门有异常扣费退款登记流程，我帮你上报。','wán quán kě yǐ， hòu qín chù zhuān mén yǒu yì cháng kòu fèi tuì kuǎn dēng jì liú chéng， wǒ bāng nǐ shàng bào。','Được chứ, bên hậu cần có quy trình đăng ký hoàn tiền cho trường hợp trừ phí bất thường, để cô báo lên giúp cháu.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_09','V306','阮明',9,'办理退款需要打印纸质付款凭证，还是只提供手机截图就行？','bàn lǐ tuì kuǎn xū yào dǎ yìn zhǐ zhì fù kuǎn píng zhèng， hái shì zhǐ tí gōng shǒu jī jié tú jiù xíng？','Để làm thủ tục hoàn tiền, cháu cần in hóa đơn thanh toán giấy, hay chỉ cần gửi ảnh chụp màn hình điện thoại thôi ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_10','V306','宿管阿姨',10,'不用打印纸质单据，直接把当时的付款截图微信发给我即可。','bù yòng dǎ yìn zhǐ zhì dān jù， zhí jiē bǎ dāng shí de fù kuǎn jié tú wēi xìn fā gěi wǒ jí kě。','Không cần in giấy đâu, cháu cứ chụp lại màn hình thanh toán lúc đó rồi gửi qua WeChat cho cô là được.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_11','V306','阮明',11,'截图我马上调取发送，大概多久能完成退款到账？','jié tú wǒ mǎ shàng diào qǔ fā sòng， dà gài duō jiǔ néng wán chéng tuì kuǎn dào zhàng？','Cháu lấy ảnh gửi ngay đây ạ, khoảng bao lâu thì tiền hoàn về ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_12','V306','宿管阿姨',12,'统一每周五集中处理退款申请，最晚本周五资金原路退回。','tǒng yī měi zhōu wǔ jí zhōng chǔ lǐ tuì kuǎn shēn qǐng， zuì wǎn běn zhōu wǔ zī jīn yuán lù tuì huí。','Cứ thứ Sáu hàng tuần là xử lý gộp các yêu cầu hoàn tiền, chậm nhất thứ Sáu tuần này tiền sẽ hoàn về đúng nguồn thanh toán.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_13','V306','阮明',13,'我明白需要等待统一处理，辛苦阿姨帮忙登记上报就行。','wǒ míng bái xū yào děng dài tǒng yī chǔ lǐ， xīn kǔ ā yí bāng máng dēng jì shàng bào jiù xíng。','Cháu hiểu rồi, phải chờ xử lý gộp mà, cô giúp đăng ký báo lên là được rồi ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_14','V306','宿管阿姨',14,'小事，下次洗衣前记得多充一点余额，避免中途停机。','xiǎo shì， xià cì xǐ yī qián jì de duō chōng yì diǎn yú é， bì miǎn zhōng tú tíng jī。','Chuyện nhỏ mà, lần sau giặt đồ nhớ nạp thêm chút tiền vào, tránh để máy dừng giữa chừng nữa nhé.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_15','V306','阮明',15,'好的，辛苦阿姨啦！','hǎo de， xīn kǔ ā yí la！','Dạ vâng, cảm ơn cô vất vả giúp cháu nhé!','AM02') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT307','S104','Gọi món mang đi ở quán gần trường',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V307','SIT307','P1','suon_se','tuy_y',NULL,'国内街边小吃支持自由调整口味、增减食材，常规外带打包无需额外收费。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_01','V307','阮明',1,'你好，我要一份杂粮煎饼，打包外带哦。','nǐ hǎo， wǒ yào yī fèn zá liáng jiān bǐng， dǎ bāo wài dài ó。','Chào chị, cho em một cái bánh tráng ngũ cốc, gói mang đi nha.','AM03') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_02','V307','店员',2,'好嘞，要不要加烤肠、生菜这些配菜呀？','hǎo lei， yào bù yào jiā kǎo cháng、 shēng cài zhè xiē pèi cài ya？','Được rồi, em có muốn thêm xúc xích nướng, xà lách không?','AM01') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_03','V307','阮明',3,'加一根烤肠就好，少放辣椒吧，我不太能吃辣。','jiā yī gēn kǎo cháng jiù hǎo， shǎo fàng là jiāo ba， wǒ bù tài néng chī là。','Thêm một cây xúc xích nướng thôi, ít ớt lại giúp em nha, em không ăn cay được lắm.','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_04','V307','店员',4,'没问题，微辣口味，两分钟就好哈。','méi wèn tí， wēi là kǒu wèi， liǎng fēn zhōng jiù hǎo hā。','Không vấn đề gì, vị cay nhẹ nha, hai phút là xong liền.','AM06') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_05','V307','阮明',5,'麻烦帮我封紧一点，我带回宿舍吃。','má fán bāng wǒ fēng jǐn yì diǎn， wǒ dài huí sù shè chī。','Chị gói cho em chắc chắn chút nha, em mang về ký túc xá ăn.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_06','V307','店员',6,'放心，肯定给你包得严严实实的。','fàng xīn， kěn dìng gěi nǐ bāo dé yán yán shí shí de。','Yên tâm đi, chị gói kín mít cho em luôn.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_07','V307','阮明',7,'谢谢老板！','xiè xiè lǎo bǎn！','Cảm ơn chị nha!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT308','S104','Báo dị ứng thực phẩm khi đặt món online',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V308','SIT308','P1','twist','ban_chinh_thuc',NULL,'国内外卖平台的用餐备注优先级很高，食材过敏、特殊口味等需求，正规商家都会优先遵从。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_01','V308','阮明',1,'你好，我刚下的订单，有重要的忌口需要备注。','nǐ hǎo， wǒ gāng xià de dìng dān， yǒu zhòng yào de jì kǒu xū yào bèi zhù。','Chào bạn, mình vừa đặt đơn xong, có mấy điều kiêng kỵ quan trọng cần ghi chú lại.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_02','V308','客服',2,'您好，请您说明具体要求，我们同步给后厨。','nín hǎo， qǐng nín shuō míng jù tǐ yāo qiú， wǒ men tóng bù gěi hòu chú。','Chào bạn, bạn cứ nói rõ yêu cầu cụ thể, chúng tôi sẽ chuyển ngay cho bếp.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_03','V308','阮明',3,'我严重对花生过敏，餐品里千万不要放任何花生制品啊。','wǒ yán zhòng duì huā shēng guò mǐn， cān pǐn lǐ qiān wàn bú yào fàng rèn hé huā shēng zhì pǐn a。','Mình bị dị ứng đậu phộng khá nặng, xin đừng cho bất kỳ chút đậu phộng nào vào món ăn nhé.','AM05') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_04','V308','客服',4,'好的，已经为您重点备注忌口花生。','hǎo de， yǐ jīng wèi nín zhòng diǎn bèi zhù jì kǒu huā shēng。','Vâng, chúng tôi đã ghi chú đặc biệt về việc kiêng đậu phộng cho đơn của bạn rồi.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_05','V308','阮明',5,'之前有商家忽略备注，差点出问题呢。','zhī qián yǒu shāng jiā hū lüè bèi zhù， chà diǎn chū wèn tí ne。','Trước đây từng có quán bỏ sót phần ghi chú này, suýt nữa xảy ra chuyện đó.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_06','V308','客服',6,'非常抱歉让您有顾虑，我们会单独叮嘱后厨的。','fēi cháng bào qiàn ràng nín yǒu gù lǜ， wǒ men huì dān dú dīng zhǔ hòu chú de。','Chúng tôi rất xin lỗi vì đã khiến bạn lo lắng, sẽ dặn dò riêng bên bếp cẩn thận hơn.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_07','V308','阮明',7,'那就麻烦你们多留意一下。','nà jiù má fán nǐ men duō liú yì yī xià。','Vậy nhờ các bạn để ý kỹ giúp mình nhé.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT309','S101','Hỏi hạn sử dụng và bảo quản thực phẩm',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V309','SIT309','P1','suon_se','tuy_y',NULL,'食品分常温、冷藏两类储存方式，错误存放会大幅缩短保质期，是日常收纳的基本常识。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_01','V309','阮明',1,'你好，我想问一下这款酸奶的保质期是多久呀？','nǐ hǎo， wǒ xiǎng wèn yī xià zhè kuǎn suān nǎi de bǎo zhì qī shì duō jiǔ ya？','Chào chị, cho em hỏi hạn sử dụng của loại sữa chua này là bao lâu vậy ạ?','AM01') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_02','V309','店员',2,'这款常温酸奶保质期三个月，不用放冰箱的。','zhè kuǎn cháng wēn suān nǎi bǎo zhì qī sān gè yuè， bù yòng fàng bīng xiāng de。','Sữa chua để ở nhiệt độ thường này hạn dùng ba tháng, không cần bỏ tủ lạnh đâu.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_03','V309','阮明',3,'那开封之后可以放多久呢？','nà kāi fēng zhī hòu kě yǐ fàng duō jiǔ ne？','Vậy sau khi mở nắp thì để được bao lâu ạ?','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_04','V309','店员',4,'开封后最好当天喝完，放久容易变质哦。','kāi fēng hòu zuì hǎo dàng tiān hē wán， fàng jiǔ róng yì biàn zhì ó。','Mở nắp rồi thì tốt nhất uống hết trong ngày, để lâu dễ bị hỏng lắm.','AM03') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_05','V309','阮明',5,'原来是这样，常温存放就可以是吧？','yuán lái shì zhè yàng， cháng wēn cún fàng jiù kě yǐ shì ba？','Ra là vậy, để ở nhiệt độ thường là được đúng không ạ?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_06','V309','店员',6,'对的，避开阳光暴晒就行，很方便的。','duì de， bì kāi yáng guāng pù shài jiù xíng， hěn fāng biàn de。','Đúng rồi, chỉ cần tránh ánh nắng trực tiếp thôi, tiện lắm.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_07','V309','阮明',7,'清楚了，谢谢你！','qīng chǔ le， xiè xiè nǐ！','Em hiểu rồi ạ, cảm ơn chị!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT310','S105','Thương lượng với hàng xóm về tiếng ồn',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V310','SIT310','P1','suon_se','ban_chinh_thuc',NULL,'国内高校宿舍普遍默认夜间十点为安静作息时间，邻里噪音问题友好协商即可解决。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_01','V310','阮明',1,'同学你好，不好意思打扰你一下哈。','tóng xué nǐ hǎo， bù hǎo yì sī dǎ rǎo nǐ yī xià hā。','Chào bạn, xin lỗi làm phiền bạn chút nha.','AM06') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_02','V310','邻居',2,'没事的，你有什么事直接说就好呀。','méi shì de， nǐ yǒu shén me shì zhí jiē shuō jiù hǎo ya。','Không sao đâu, có chuyện gì bạn cứ nói thẳng luôn nha.','AM01') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_03','V310','阮明',3,'我晚上要复习备考，你们宿舍声音稍微有点大呢。','wǒ wǎn shàng yào fù xí bèi kǎo， nǐ men sù shè shēng yīn shāo wēi yǒu diǎn dà ne。','Buổi tối mình cần ôn bài thi, phòng các bạn hơi ồn một chút.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_04','V310','邻居',4,'天啊，真的不好意思，我们没注意音量。','tiān a， zhēn de bù hǎo yì sī， wǒ men méi zhù yì yīn liàng。','Trời ơi, thật xin lỗi bạn, tụi mình không để ý âm lượng.','AM05') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_05','V310','阮明',5,'没关系的，就是希望晚上十点后可以安静一点。','méi guān xì de， jiù shì xī wàng wǎn shàng shí diǎn hòu kě yǐ ān jìng yì diǎn。','Không sao đâu, mình chỉ mong sau mười giờ tối thì yên tĩnh hơn một chút thôi.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_06','V310','邻居',6,'没问题，我们马上小声，之后一定注意！','méi wèn tí， wǒ men mǎ shàng xiǎo shēng， zhī hòu yí dìng zhù yì！','Không vấn đề gì, tụi mình nhỏ tiếng lại ngay, sau này chắc chắn sẽ chú ý!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_07','V310','阮明',7,'太感谢你的理解啦！','tài gǎn xiè nǐ de lǐ jiě la！','Cảm ơn bạn đã thông cảm nhiều nha!','AM02') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT311','S106','Xin phép vào lớp muộn',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V311','SIT311','P1','suon_se','ban_chinh_thuc',NULL,'国内课堂迟到必须主动致歉并说明原因，征得老师同意后方可进入教室，是基本课堂礼仪。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_01','V311','阮明',1,'老师对不起，我上课迟到了，非常抱歉！','lǎo shī duì bù qǐ， wǒ shàng kè chí dào le， fēi cháng bào qiàn！','Thầy ơi em xin lỗi, em đi học trễ, thật sự rất xin lỗi thầy!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_02','V311','老师',2,'怎么迟到了呢？是什么原因造成的？','zěn me chí dào le ne？ shì shén me yuán yīn zào chéng de？','Sao lại trễ vậy? Nguyên nhân là gì thế?','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_03','V311','阮明',3,'我早上出门晚了，遇上堵车，耽误了时间。','wǒ zǎo shàng chū mén wǎn le， yù shàng dǔ chē， dān wù le shí jiān。','Sáng nay em ra khỏi nhà hơi muộn, lại gặp kẹt xe nên bị trễ giờ ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_04','V311','老师',4,'下次一定要把控好时间，不要再迟到了。','xià cì yí dìng yào bǎ kòng hǎo shí jiān， bú yào zài chí dào le。','Lần sau nhất định phải canh giờ cho tốt, đừng để trễ nữa nhé.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_05','V311','阮明',5,'我记住了，以后肯定提前出门。','wǒ jì zhù le， yǐ hòu kěn dìng tí qián chū mén。','Em nhớ rồi ạ, sau này em sẽ ra khỏi nhà sớm hơn.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_06','V311','老师',6,'行，快进来入座听课吧，不要耽误学习。','xíng， kuài jìn lái rù zuò tīng kè ba， bú yào dān wù xué xí。','Được rồi, vào chỗ ngồi nghe giảng nhanh đi, đừng để ảnh hưởng việc học.','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_07','V311','阮明',7,'谢谢老师谅解！','xiè xiè lǎo shī liàng jiě！','Em cảm ơn thầy đã thông cảm ạ!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT312','S106','Xin nghỉ học vì lý do cá nhân',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V312','SIT312','P1','suon_se','ban_chinh_thuc',NULL,'国内高校禁止无故缺课，所有缺勤都需要提前报备请假，否则会记录考勤扣分。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_01','V312','阮明',1,'辅导员您好，我想申请今天下午的事假。','fǔ dǎo yuán nín hǎo， wǒ xiǎng shēn qǐng jīn tiān xià wǔ de shì jià。','Cô ơi, em muốn xin nghỉ phép chiều nay ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_02','V312','辅导员',2,'可以的，简单说一下请假的原因吧。','kě yǐ de， jiǎn dān shuō yī xià qǐng jià de yuán yīn ba。','Được thôi, em nói qua lý do xin nghỉ nhé.','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_03','V312','阮明',3,'我有重要的个人私事需要处理，没办法延后。','wǒ yǒu zhòng yào de gè rén sī shì xū yào chǔ lǐ， méi bàn fǎ yán hòu。','Em có việc riêng quan trọng cần giải quyết, không thể hoãn lại được ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_04','V312','辅导员',4,'了解了，我给你登记考勤，准予请假。','liǎo jiě le， wǒ gěi nǐ dēng jì kǎo qín， zhǔn yǔ qǐng jià。','Cô hiểu rồi, để cô ghi nhận vào điểm danh, cho em nghỉ phép.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_05','V312','阮明',5,'谢谢老师，落下的课程我会及时补回来的。','xiè xiè lǎo shī， là xià de kè chéng wǒ huì jí shí bǔ huí lái de。','Em cảm ơn cô, bài học bị lỡ em sẽ bổ sung kịp thời ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_06','V312','辅导员',6,'一定要跟上进度，不要拖欠学习内容。','yí dìng yào gēn shàng jìn dù， bú yào tuō qiàn xué xí nèi róng。','Nhất định phải theo kịp tiến độ, đừng để nợ bài đó.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_07','V312','阮明',7,'我明白的，辛苦老师了！','wǒ míng bái de， xīn kǔ lǎo shī le！','Em hiểu rồi ạ, cô vất vả rồi!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT313','S107','Xin gia hạn nộp bài tập',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V313','SIT313','P1','twist','ban_chinh_thuc',NULL,'大学作业延期属于特殊情况，老师会酌情处理，但不支持频繁、长期延期；超规定延期时限会扣除课程平时成绩。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_01','V313','阮明',1,'老师您好，占用您一点课余时间，我想跟您申请课程作业延期提交。','lǎo shī nín hǎo， zhàn yòng nín yì diǎn kè yú shí jiān， wǒ xiǎng gēn nín shēn qǐng kè chéng zuò yè yán qī tí jiāo。','Thầy ơi, xin phép chiếm chút thời gian của thầy, em muốn xin thầy cho gia hạn nộp bài tập ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_02','V313','老师',2,'你先简单说明理由，课堂规定无故拖延作业提交时间是不允许的哦。','nǐ xiān jiǎn dān shuō míng lǐ yóu， kè táng guī dìng wú gù tuō yán zuò yè tí jiāo shí jiān shì bù yǔn xǔ de ó。','Em nói rõ lý do trước đã, quy định lớp mình là không được tự ý trì hoãn nộp bài vô cớ đâu nhé.','AM03') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_03','V313','阮明',3,'昨天一整天突发肠胃不适，头晕乏力卧床休息，完全没有精力动笔写作业。','zuó tiān yī zhěng tiān tū fā cháng wèi bù shì， tóu yūn fá lì wò chuáng xiū xī， wán quán méi yǒu jīng lì dòng bǐ xiě zuò yè。','Hôm qua cả ngày em bị đau bụng đột ngột, chóng mặt mệt mỏi phải nằm nghỉ, hoàn toàn không có sức để làm bài ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_04','V313','老师',4,'身体不舒服我可以理解，生病属于合理特殊情况，不过延期有严格时限要求。','shēn tǐ bù shū fú wǒ kě yǐ lǐ jiě， shēng bìng shǔ yú hé lǐ tè shū qíng kuàng， bù guò yán qī yǒu yán gé shí xiàn yāo qiú。','Ốm thì thầy hiểu, bệnh là trường hợp đặc biệt hợp lý, nhưng việc gia hạn vẫn có quy định thời hạn nghiêm ngặt.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_05','V313','阮明',5,'我原本计划今天傍晚准时上交，现在还差一半内容没能完成。','wǒ yuán běn jì huà jīn tiān bàng wǎn zhǔn shí shàng jiāo， xiàn zài hái chà yí bàn nèi róng méi néng wán chéng。','Em vốn định chiều tối nay nộp bài đúng hạn, nhưng giờ vẫn còn thiếu một nửa nội dung chưa làm xong ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_06','V313','老师',6,'按照学院统一规定，单次作业最多只能延期一天，不能无限延后。','àn zhào xué yuàn tǒng yī guī dìng， dān cì zuò yè zuì duō zhǐ néng yán qī yī tiān， bù néng wú xiàn yán hòu。','Theo quy định chung của khoa, mỗi bài chỉ được gia hạn tối đa một ngày thôi, không thể kéo dài mãi được.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_07','V313','阮明',7,'只延期一天对我来说完全足够，今晚我熬夜赶工，保证完整写完所有内容。','zhǐ yán qī yī tiān duì wǒ lái shuō wán quán zú gòu， jīn wǎn wǒ áo yè gǎn gōng， bǎo zhèng wán zhěng xiě wán suǒ yǒu nèi róng。','Chỉ cần gia hạn một ngày là đủ với em rồi ạ, tối nay em sẽ thức khuya làm cho xong, đảm bảo hoàn thành đầy đủ nội dung.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_08','V313','老师',8,'这次看你身体不适特殊通融一次，往后不管任何理由都尽量按时完成。','zhè cì kàn nǐ shēn tǐ bù shì tè shū tōng róng yī cì， wǎng hòu bù guǎn rèn hé lǐ yóu dōu jǐn liàng àn shí wán chéng。','Lần này thấy em ốm nên thầy châm chước đặc biệt một lần, sau này dù lý do gì cũng phải cố gắng hoàn thành đúng hạn.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_09','V313','阮明',9,'我记下老师的提醒，下次一定提前规划时间，不会再出现延期情况。','wǒ jì xià lǎo shī de tí xǐng， xià cì yí dìng tí qián guī huà shí jiān， bú huì zài chū xiàn yán qī qíng kuàng。','Em ghi nhớ lời nhắc của thầy rồi ạ, lần sau em sẽ sắp xếp thời gian trước, sẽ không để xảy ra trễ hạn nữa.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_10','V313','老师',10,'延期提交的作业明天傍晚六点前必须交到办公室，逾期依旧会扣除平时分。','yán qī tí jiāo de zuò yè míng tiān bàng wǎn liù diǎn qián bì xū jiāo dào bàn gōng shì， yú qī yī jiù huì kòu chú píng shí fēn。','Bài nộp trễ thì chậm nhất sáu giờ chiều mai phải nộp tới văn phòng, nếu trễ hạn vẫn sẽ bị trừ điểm quá trình.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_11','V313','阮明',11,'我会定好闹钟准时送达，不会错过截止时间。','wǒ huì dìng hǎo nào zhōng zhǔn shí sòng dá， bú huì cuò guò jié zhǐ shí jiān。','Em sẽ đặt báo thức để nộp đúng giờ, sẽ không bỏ lỡ thời hạn đâu ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_12','V313','老师',12,'作业提交后我会优先批改，有错误再单独跟你讲解。','zuò yè tí jiāo hòu wǒ huì yōu xiān pī gǎi， yǒu cuò wù zài dān dú gēn nǐ jiǎng jiě。','Sau khi bài được nộp thầy sẽ ưu tiên chấm trước, có lỗi gì thầy sẽ giải thích riêng cho em.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_13','V313','阮明',13,'太感谢老师体谅我的身体状况，我一定认真完成作业。','tài gǎn xiè lǎo shī tǐ liàng wǒ de shēn tǐ zhuàng kuàng， wǒ yí dìng rèn zhēn wán chéng zuò yè。','Em cảm ơn thầy rất nhiều vì đã thông cảm cho tình trạng sức khỏe của em, em nhất định sẽ làm bài thật nghiêm túc ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_14','V313','老师',14,'好好休息，别过度熬夜伤身体。','hǎo hǎo xiū xī， bié guò dù áo yè shāng shēn tǐ。','Nghỉ ngơi cho tốt vào, đừng thức khuya quá mà hại sức khỏe.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_15','V313','阮明',15,'好的，谢谢老师！','hǎo de， xiè xiè lǎo shī！','Dạ vâng, em cảm ơn thầy!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT314','S107','Trao đổi phân công trong làm việc nhóm',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V314','SIT314','P1','suon_se','tuy_y',NULL,'国内大学小组作业讲究全员参与、公平分工，团队协作度是评分的重要标准。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_01','V314','张浩',1,'我们小组作业还没分工，今天赶紧定一下吧？','wǒ men xiǎo zǔ zuò yè hái méi fēn gōng， jīn tiān gǎn jǐn dìng yī xià ba？','Bài tập nhóm mình vẫn chưa phân công, hôm nay chốt luôn nhé?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_02','V314','阮明',2,'好呀，我们按各自特长分工，效率会更高。','hǎo ya， wǒ men àn gè zì tè cháng fēn gōng， xiào lǜ huì gèng gāo。','Ừ được đó, mình phân công theo sở trường của từng người, làm vậy hiệu quả hơn.','AM01') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_03','V314','张浩',3,'我擅长搜集资料和写文稿，PPT制作你可以吗？','wǒ shàn cháng sōu jí zī liào hé xiě wén gǎo，PPT zhì zuò nǐ kě yǐ ma？','Mình mạnh về thu thập tài liệu với viết nội dung, cậu làm PPT được không?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_04','V314','阮明',4,'没问题，我很擅长做PPT，这个交给我。','méi wèn tí， wǒ hěn shàn cháng zuò PPT， zhè ge jiāo gěi wǒ。','Không vấn đề gì, mình làm PPT khá ổn, để phần đó cho mình.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_05','V314','张浩',5,'那最后课堂汇报，我们两个人一起配合。','nà zuì hòu kè táng huì bào， wǒ men liǎng gè rén yì qǐ pèi hé。','Vậy phần thuyết trình cuối cùng trên lớp, hai đứa mình cùng phối hợp nhé.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_06','V314','阮明',6,'可以，我们做完互相检查，避免出错。','kě yǐ， wǒ men zuò wán hù xiāng jiǎn chá， bì miǎn chū cuò。','Được, làm xong mình kiểm tra chéo cho nhau, tránh sai sót.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_07','V314','张浩',7,'完美，那我们各自开工！','wán měi， nà wǒ men gè zì kāi gōng！','Tuyệt vời, vậy mỗi đứa bắt tay vào làm phần của mình thôi!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT315','S106','Thuyết trình trước lớp, xin lỗi vì thiếu chuẩn bị',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V315','SIT315','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内课堂展示允许轻微失误，主动诚恳认错、复盘问题，不会大幅扣分。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_01','V315','阮明',1,'老师、各位同学，非常抱歉，我本次的课堂汇报准备不足。','lǎo shī、 gè wèi tóng xué， fēi cháng bào qiàn， wǒ běn cì de kè táng huì bào zhǔn bèi bù zú。','Thưa thầy/cô và các bạn, em thật sự xin lỗi vì lần thuyết trình này em chuẩn bị chưa kỹ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
